    no_title:'El mensaje correcto, <span style="color:#06B6D4">al canal correcto.</span>',
    no_desc:'Notice unifica la comunicación operacional de tu flota: alertas automáticas de GPS, mensajes a conductores por WhatsApp o push, notificaciones de vencimiento y avisos masivos. Todo desde un solo panel, con historial completo.',
