    no_stat_4:'Alertas sin intervención manual',
    no_feat_title:'Comunicación operacional que realmente funciona',
    no_f1_title:'WhatsApp integrado',
    no_f1_desc:'Envía alertas, reportes y mensajes directamente al WhatsApp del conductor. Sin apps adicionales: el conductor lo recibe en el teléfono que ya usa.',
    no_f2_title:'Push notifications',
    no_f2_desc:'Notificaciones push segmentadas por conductor, vehículo, ruta o zona. Con acuse de recibo y confirmación de lectura desde la app PilotOS.',
    no_f3_title:'Alertas GPS automáticas',
    no_f3_desc:'Dispara mensajes automáticos por geocerca, exceso de velocidad, parada no programada o vehículo fuera de ruta — sin configuración por evento.',
    no_f4_title:'Email y SMS',
    no_f4_desc:'Canal de respaldo para alertas críticas. Configura reglas de escalación: si el conductor no responde en X minutos, escala al supervisor por email.',
    no_f5_title:'Plantillas de mensajes',
    no_f5_desc:'Crea plantillas reutilizables con variables dinámicas ({nombre}, {vehículo}, {velocidad}) para agilizar el envío de mensajes operacionales recurrentes.',
    no_f6_title:'Historial y auditoría',
    no_f6_desc:'Registro completo de todas las comunicaciones: quién envió, a quién, cuándo y si fue entregado. Exportable para auditorías y reportes de cumplimiento.',
    no_mc_title:'Un mensaje, todos los canales',
    no_mc_desc:'Define una regla de alerta una sola vez y Notice decide automáticamente el mejor canal según el tipo de evento, la urgencia y las preferencias del destinatario.',
