    dq_badge:'Análise de Condução',
    dq_title:'Converta dados de condução em <span style="color:#F59E0B">ação preventiva</span>',
    dq_desc:'DriveIQ analisa em tempo real o comportamento de cada motorista: excesso de velocidade, frenagens bruscas, acelerações agressivas e tempo em marcha lenta. Pontuações, alertas e coaching para reduzir acidentes e combustível.',
    dq_stat_1:'Redução de combustível',
    dq_stat_2:'Menos incidentes viários',
    dq_stat_3:'Cobertura da frota',
    dq_stat_4:'Monitoramento contínuo',
    dq_feat_title:'Tudo que você precisa para melhorar a condução',
    dq_f1_title:'Score de condução (0–100)',
    dq_f1_desc:'Pontuação calculada em tempo real por motorista. Desconta pontos por excesso de velocidade, frenagens bruscas, acelerações agressivas, curvas, uso do telefone, fadiga, cinto de segurança e tempo em marcha lenta.',
    dq_f2_title:'8 tipos de eventos detectados',
    dq_f2_desc:'Excesso de velocidade, frenagem brusca, aceleração agressiva, curva brusca, uso do telefone ao volante, fadiga do motorista, cinto desapertado e tempo excessivo em marcha lenta — cada um com severidade e localização exata.',
    dq_f3_title:'Ranking e coaching automático',
    dq_f3_desc:'Ranking comparativo entre todos os motoristas da empresa. O sistema gera até 3 dicas de coaching personalizadas com base nos eventos mais frequentes de cada motorista.',
    dq_f4_title:'Painel de veículos em tempo real',
    dq_f4_desc:'Posição exata, velocidade atual e estado online/offline de cada unidade. Tipos de veículos personalizáveis para adaptar os parâmetros de avaliação a cada categoria da sua frota.',
    dq_f5_title:'Grupos de veículos',
    dq_f5_desc:'Organize sua frota em grupos por zona, tipo de serviço ou turno. Filtre eventos, scores e relatórios por grupo. Ideal para empresas com múltiplas operações ou filiais.',
    dq_f6_title:'Integração nativa com Appogio',
    dq_f6_desc:'Consome diretamente os dados da sua plataforma GPS. Sem configuração adicional: veículos, motoristas e eventos já registrados no Appogio aparecem automaticamente no DriveIQ.',
    dq_ss_title:'Veja o DriveIQ em detalhe',
    dq_video_title:'DriveIQ em ação',
    dq_cta_title:"Pronto para vender aos seus clientes o controle da direção?",
    dq_cta_desc:"Solicite uma demonstração do DriveIQ e ofereça às frotas dos seus clientes a pontuação por motorista, os eventos de direção e os relatórios, com a sua marca.",
    dq_cta_btn:'Solicitar Demo do DriveIQ',
    ip_badge:'Inspeções Digitais',
    ip_title:'Do papel ao digital em <span style="color:#3B82F6">minutos. Sem fricções.</span>',
    ip_desc:'InspectPro substitui os formulários físicos por checklists inteligentes, assinatura digital, fotografias georreferenciadas e fluxos de aprovação. Tudo fica registrado, rastreável e disponível como relatório PDF instantaneamente.',
    ip_stat_1:'Menos tempo por inspeção',
    ip_stat_2:'Digitalização de registros',
    ip_stat_3:'Papéis eliminados',
    ip_stat_4:'Modelos personalizáveis',
    ip_stat_4_val:'Ilimitado',
    ip_feat_title:'Inspeções inteligentes do início ao fim',
    ip_f1_title:'Modelos ilimitados e personalizáveis',
    ip_f1_desc:'Crie, clone e edite checklists com texto, fotos, seleção múltipla, assinatura digital e avaliação. Cada empresa configura seus próprios formulários conforme sua operação.',
    ip_f2_title:'Fluxo de aprovação supervisor',
    ip_f2_desc:'O supervisor aprova ✅ ou rejeita ❌ com motivo. Ao rejeitar, o motorista recebe a inspeção de volta com aviso laranja e deve corrigi-la. Os planos de ação ficam registrados no histórico.',
    ip_f3_title:'IA + OCR de placas',
    ip_f3_desc:'Analisa formulários físicos a partir de uma foto usando inteligência artificial. OCR automático de placas veiculares para registrar inspeções sem digitar manualmente a matrícula.',
    ip_f4_title:'Alertas de vencimento de documentos',
    ip_f4_desc:'Monitora seguros, revisões técnicas, licenças e qualquer documento do veículo. Gera alertas automáticos antes do vencimento para que a frota sempre opere em conformidade.',
    ip_f5_title:'Relatórios PDF, CSV e dashboard',
    ip_f5_desc:'Relatórios PDF com assinatura digital e fotos georreferenciadas. Exportação para CSV ou ZIP. Dashboard de conformidade com inspeções esperadas vs realizadas, tendências e análises.',
    ip_f6_title:'QR, notificações push e API',
    ip_f6_desc:'QR por veículo ou formulário. Notificações push ao motorista ao rejeitar inspeção. API keys e webhooks para integração com sistemas externos. Logs de auditoria completos.',
    ip_roles_title:'Acesso inteligente para cada perfil',
    ip_role1_badge:'Motorista / Usuário',
    ip_role1_title:'Operação em campo',
    ip_role2_badge:'Supervisor',
