    po_video_title:'Veja o PilotOS em ação',
    po_cta_title:"Pronto para vender o controle de motoristas aos seus clientes?",
    po_cta_desc:"Ofereça a eles o prontuário digital de cada motorista, com os vencimentos controlados sozinhos e tudo acessível de qualquer lugar, com a sua marca.",
    po_cta_btn:'Solicitar Demo do PilotOS',
    cf_badge:'Câmeras Veiculares',
    cf_title:'Sua frota, <span style="color:#7C3AED">vista em tempo real.</span>',
    cf_desc:'CamFleet integra câmeras dashcam e de cabine com sua plataforma GPS. Streaming ao vivo, gravação contínua com backup em nuvem, detecção automática de eventos (frenagens, colisões, sonolência) e evidência legal instantânea para qualquer incidente.',
    cf_stat_1:'Gravação contínua',
    cf_stat_2:'Para acessar gravação ao vivo',
    cf_stat_3:'Precisão na detecção de eventos',
    cf_stat_4:'Backup local + nuvem criptografada',
    cf_feat_title:'Mais que uma câmera. Um sistema de vigilância completo.',
    cf_f1_title:'Streaming HLS / RTSP / WebRTC',
    cf_f1_desc:'Veja ao vivo todas as câmeras pelo navegador. O servidor MediaMTX retransmite o stream JT1078 da dashcam em HLS, RTSP e WebRTC sem instalar plugins ou apps.',
    cf_f2_title:'Protocolo nativo JT808 / JT1078',
    cf_f2_desc:'Conexão direta com dashcams Jimi e Concox (JC181, JC450, DC600) pelo protocolo JT808/JT1078. Sem conversores externos: a câmera conecta diretamente ao servidor.',
    cf_f3_title:'Clipes por evento + download',
    cf_f3_desc:'Cada evento gera um clipe de vídeo associado: tipo de evento, veículo, data e hora. Baixe qualquer clipe pelo painel sem acessar o dispositivo físico.',
    cf_f4_title:'Alertas por WhatsApp com evidência',
    cf_f4_desc:'Configure contatos de alerta por veículo. Quando ocorre um evento, o sistema envia o aviso pelo WhatsApp com o clipe de vídeo anexado como evidência imediata.',
    cf_f5_title:'GPS + motoristas sincronizados',
    cf_f5_desc:'Cada câmera tem um veículo associado e opcionalmente um motorista. O mapa mostra a posição em tempo real e você pode ver o stream diretamente no pin do veículo.',
    cf_f6_title:'Dashboard de eventos por tipo e dia',
    cf_f6_desc:'Resumo executivo com total de câmeras, streams ativos, eventos por tipo e tendência diária. Identifique veículos com mais incidentes de um relance.',
    cf_hw_title:'Funciona com os equipamentos que você já tem',
    cf_hw_desc:'CamFleet suporta os principais fabricantes de câmeras veiculares. Se você já tem hardware instalado, provavelmente é compatível.',
    cf_hw4_title:'Outro modelo?',
    cf_hw4_desc:'Consulte a compatibilidade com seu hardware atual sem compromisso',
    cf_ss_title:'CamFleet em detalhe',
    cf_cta_title:"Pronto para vender vídeo a bordo aos seus clientes?",
    cf_cta_desc:"Solicite uma demonstração do CamFleet e ofereça aos seus clientes o vídeo a bordo que protege a operação deles, com a sua marca.",
    cf_cta_btn:'Solicitar Demo do CamFleet',
    tr_badge:'Rastreamento de Ativos BLE',
    tr_title:'Saiba onde está <span style="color:#10B981">cada ativo, sempre.</span>',
    tr_desc:'TagRadar usa etiquetas BLE de longa duração captadas por antenas fixas ou móveis. O mapa mostra em tempo real a última antena que detectou cada ativo. Sem GPS, sem SIM: funciona em interiores, pátios e depósitos onde o GPS não chega.',
    tr_stat_1:'Tecnologia de última geração',
    tr_stat_2:'Frequência de atualização do mapa',
    tr_stat_3:'Duração da bateria do tag',
    tr_stat_4:'Sem custo de conectividade',
    tr_feat_title:'Do caos do inventário ao controle total',
    tr_f1_title:'Última posição por antena',
    tr_f1_desc:'Cada tag BLE é captado pela antena mais próxima. O mapa mostra em tempo real a posição da antena que o detectou por último, atualizado a cada 20 segundos.',
    tr_f2_title:'Geocercas com alertas de entrada/saída',
    tr_f2_desc:'Defina zonas para cada ativo ou grupo. Receba alerta imediato quando um equipamento entra ou sai da área designada. Configurável por zona e ativo.',
    tr_f3_title:'Histórico de rota 24 horas',
    tr_f3_desc:'Consulte o histórico completo de detecções de qualquer ativo nas últimas 24 horas: antena que o viu, hora exata e posição. Rastreabilidade total.',
    tr_f4_title:'Estados de ativo em tempo real',
    tr_f4_desc:'<strong>Ao vivo</strong> (detectado há &lt;5 min), <strong>Recente</strong> (&lt;2 h) ou <strong>Inativo</strong> (&gt;2 h). De uma olhada você sabe quais ativos estão sendo monitorados e quais estão sem reportar há tempo.',
    tr_f5_title:'Administração de ativos e antenas',
    tr_f5_desc:'Registre, edite e exclua tags com nome e descrição. Consulte quais antenas estão ativas, quando reportaram pela última vez e quantos ativos captaram.',
    tr_f6_title:'App Android + SSO com Appogio',
    tr_f6_desc:'Acesse pelo app Android nativo com as mesmas credenciais do GPS Software. As antenas reportam via APK scanner BLE sem necessidade de hardware adicional.',
    tr_uc_title:'Para qualquer setor com ativos para rastrear',
    tr_ss_title:'TagRadar em detalhe',
    tr_video_title:'Veja o TagRadar em ação',
    tr_cta_title:"Pronto para vender o rastreamento de cada ativo aos seus clientes?",
    tr_cta_desc:"O TagRadar funciona sem GPS e sem SIM. Ative-o na conta do seu cliente e comece a faturar o rastreamento dos ativos dele desde o primeiro dia.",
    tr_cta_btn:'Solicitar Demo do TagRadar',
