    no_title:'A mensagem certa, <span style="color:#06B6D4">no canal certo.</span>',
    no_desc:'Notice unifica a comunicação operacional da sua frota: alertas automáticos de GPS, mensagens para motoristas por WhatsApp ou push, notificações de vencimento e avisos em massa. Tudo em um único painel, com histórico completo.',
