    no_feat_title:'Comunicação operacional que realmente funciona',
    no_f1_title:'WhatsApp integrado',
    no_f1_desc:'Envie alertas, relatórios e mensagens diretamente ao WhatsApp do motorista. Sem apps adicionais: o motorista recebe no telefone que já usa.',
    no_f2_title:'Notificações push',
    no_f2_desc:'Notificações push segmentadas por motorista, veículo, rota ou zona. Com aviso de recebimento e confirmação de leitura pelo app PilotOS.',
    no_f3_title:'Alertas GPS automáticos',
    no_f3_desc:'Dispara mensagens automáticas por geocerca, excesso de velocidade, parada não programada ou veículo fora de rota — sem configuração por evento.',
    no_f4_title:'E-mail e SMS',
    no_f4_desc:'Canal de backup para alertas críticos. Configure regras de escalonamento: se o motorista não responder em X minutos, escala ao supervisor por e-mail.',
    no_f5_title:'Modelos de mensagens',
    no_f5_desc:'Crie modelos reutilizáveis com variáveis dinâmicas ({nome}, {veículo}, {velocidade}) para agilizar o envio de mensagens operacionais recorrentes.',
    no_f6_title:'Histórico e auditoria',
    no_f6_desc:'Registro completo de todas as comunicações: quem enviou, para quem, quando e se foi entregue. Exportável para auditorias e relatórios de conformidade.',
    no_mc_title:'Uma mensagem, todos os canais',
    no_mc_desc:'Defina uma regra de alerta uma única vez e o Notice decide automaticamente o melhor canal conforme o tipo de evento, a urgência e as preferências do destinatário.',
    no_ss_title:'Notice em detalhe',
    no_video_title:'Veja o Notice em ação',
