    nw_4: "Insurers and large fleets",
    nw_5: "Handle WhatsApp from a company number instead of someone’s personal phone.",
    nw_6: "Tell the end customer about expiries, billing and service news without relying on email.",
    nw_7: "Automatic expiry reminders",
    nw_8: "WhatsApp alerts",
    nw_9: "Each client or department can have its own: sales, support, fleet alerts.",
    nw_10: "Each extract is tied to its contract, its vehicle and its dates, which is exactly what gets checked on the road.",
    nw_11: "Each reseller goes out to sell on their own, with their own brand and their own people. You grow into cities and sectors where you have no team, without adding a single salary.",
    nw_12: "Each with their own brand and domain",
    nw_13: "Calendar and inbox",
    nw_14: "Campaigns to your own contact lists, with tracking of what was sent.",
    nw_15: "Campaigns and notices to contact lists, with the sending pace controlled so the number is not exposed.",
    nw_16: "Features",
    nw_17: "Clients with their own ERP",
    nw_18: "Clients with custom software",
    nw_19: "Sales and marketing",
    nw_20: "Customer communication",
    nw_21: "Service continuity",
    nw_22: "Contract, vehicle and validity",
    nw_23: "Contracts with companies to take workers to and from work.",
    nw_24: "Any small team",
    nw_25: "Any",
    nw_26: "When a client asks for a system that is not on the list, we connect it. It is a routine request, not a special project: it is exactly what we do every month.",
    nw_27: "How many devices are reporting, how many are down and how many never reported since they were registered. The number at the top already tells you if the day is going well or badly.",
    nw_28: "How to explain it",
    nw_29: "How long it has been down",
    nw_30: "Said the way you say it to your client",
    nw_31: "GPS distributors",
    nw_32: "Documentation for the technical team",
    nw_33: "Where GPS data feeds risk calculation, the premium or claims reporting.",
    nw_34: "FUEC up to date, without redoing it by hand",
    nw_35: "The FUEC is the document a special transport vehicle must carry for the whole trip. Without it, the journey is not compliant.",
    nw_36: "The Single Contract Extract Form is mandatory for special transport in Colombia: school, corporate, tourism and health. Here it is issued, stored and consulted from the same account you use for your tracking software.",
    nw_37: "The case it is named for: flagging units about to expire before you lose the renewal.",
    nw_38: "The client who says “I have my own system”: that is exactly the sale you win with this.",
    nw_39: "Email gets lost and SMS costs money. WhatStar links WhatsApp numbers to your platform so fleet alerts, customer service and campaigns go out through the channel people open every day.",
    nw_40: "The time breakdown separates the urgent from the old: under an hour, 1 to 6, 6 to 24, 1 to 7 days, 7 to 30, and over 30 days.",
    nw_41: "The document the law requires",
    nw_42: "The ranking shows which customers have the most devices down, so you can start with the one closest to complaining.",
    nw_43: "The reseller hangs off you: you see their units, you invoice them, and you can activate or suspend them. If a reseller leaves, their customers do not leave with the platform.",
    nw_44: "The reseller has their own name, logo, colours and web address. Their end customer sees neither the reseller’s brand above nor yours below.",
    nw_45: "Issued from your panel account",
    nw_46: "Companies with dozens or hundreds of vehicles that cannot check device by device every day.",
    nw_47: "Special transport companies",
    nw_48: "Companies that must tell their own customer something: arrival, delay, delivery, incident.",
    nw_49: "Companies already running SAP, Siigo, World Office or another system, who have no intention of changing it for GPS.",
    nw_50: "On screen",
    nw_51: "In real time, not the next day",
    nw_52: "Sign in with your panel account",
    nw_53: "Bulk sending, under control",
    nw_54: "Support and workshop teams",
    nw_55: "Fleets with end customers",
    nw_56: "Medium and large fleets",
    nw_57: "Out of service, a customer-wide failure, no data or SIM, vehicle not in use... and when there is not enough information it says so plainly instead of making up a cause.",
    nw_58: "Searchable history",
    nw_59: "Today and the next 7 days",
    nw_60: "Integrations · WebService",
    nw_61: "The application comes with its own user manual, reachable from the login screen.",
    nw_62: "The customer base stays yours",
    nw_63: "The likely cause, without guessing",
    nw_64: "The connection is made through web services with dedicated credentials and scoped permissions. The client’s system sees what it should see, and nothing else.",
    nw_65: "Data travels both ways",
    nw_66: "The list of repeat offenders: the ones that go down, come back and go down again. That is where you lose the customer without noticing.",
    nw_67: "Most distributors are surprised by the very first screen.",
    nw_68: "Conversations and sends are stored on the platform, not on the phone of an employee who leaves tomorrow.",
    nw_69: "Those legally required to carry the FUEC on every trip.",
    nw_70: "We connect WhatsApp to your platform.",
    nw_71: "We will show you how to issue it from your own account.",
    nw_72: "Lists by area",
    nw_73: "It reaches you wherever you look",
    nw_74: "What needs doing today and what is coming this week, without opening anything else. The rest stays stored and out of the way.",
    nw_75: "Data is sent the moment it happens, so the client’s system can react while it still matters.",
    nw_76: "Issued documents are stored and can be looked up again whenever an authority or the client asks for them.",
    nw_77: "Tracking software events go out by WhatsApp with the wording you define: speeding, geofence entry and exit, power cut, and whatever else you configure.",
    nw_78: "The ones that fail again and again",
    nw_79: "Those who need vehicle position to flow into their dispatch, order or traceability system.",
    nw_80: "Manual included",
    nw_81: "More than 380 connections already running",
    nw_82: "No large client changes their systems just to add GPS. That is why our platform connects to what the client already uses: their ERP, their billing, their fuel control, their insurance system. And if the one they need is not on the list, we connect it.",
    nw_83: "It is not a generic form: it is made for companies moving schoolchildren, staff, tourists and patients.",
    nw_84: "This is not a brochure promise: these are integrations already running today with real clients. When you sell, you are not selling future development.",
    nw_85: "No need to log in and check: the alert arrives on its own when something goes down, with the device and the affected customer.",
    nw_86: "No new user to create and no password to remember: it is the same one you use for your tracking software.",
    nw_87: "Phone notification, email and WhatsApp. Whoever does not open the app finds out anyway.",
    nw_88: "Our platform can hand data to the client’s system and also receive from it. This is not just exporting a file.",
    nw_89: "Logistics operators",
    nw_90: "Team organisation",
