    nw_98: "What it does",
    nw_99: "Reminders for collections, paperwork and errands that today live in a notebook or in someone’s head.",
    nw_100: "Reseller network",
    nw_101: "Remindo warns you before, not after.",
    nw_102: "Remindo is your operation’s task list, with one difference: it knows when your GPS units expire and warns you on its own, before the customer drops off the service.",
    nw_103: "Split the day’s work between technicians and keep a record of what was done and what is still pending.",
