    nw_130: "Thirty days before, seven days before and on the day itself: the reminder is created automatically with the units about to expire. Nobody has to remember.",
    nw_131: "Tourism and patient transport",
    nw_132: "A chatbot handles the repetitive part and leaves to a human what genuinely needs one.",
    nw_133: "A device that is off means a lost invoice and a client walking away. FleetWatch checks your fleet every five minutes, tells you how long each device has been down and gives you the likely cause, with its confidence level.",
    nw_134: "You set each one’s price",
    nw_135: "You set the reseller’s price and they set the end customer’s. The difference is your margin, and you control it reseller by reseller.",
    nw_136: "Several numbers at once",
    nw_137: "Sell more without hiring more",
    nw_138: "See at a glance which devices of which customers stopped reporting, before the customer calls to complain.",
