    ax_tagstat: "<strong>Live</strong> (detected &lt;5 min ago), <strong>Recent</strong> (&lt;2 h) or <strong>Inactive</strong> (&gt;2 h). At a glance you know which assets are being monitored and which haven’t reported in a while.",
