    ax_0: "(>2 h). At a glance you know which assets are being monitored and which haven't reported in a while.",
    ax_1: "1 – 10 vehicles",
    ax_2: "11 – 50 vehicles",
    ax_3: "51 – 200 vehicles",
    ax_4: "WhatsApp alerts with the clip as evidence",
    ax_5: "Onboard app: driver + monitor",
    ax_6: "Appogio operates as an invisible technology engine. Your brand is at the front, your customers don't know Appogio exists, and the business relationship is 100% yours.",
    ax_7: "Assign vehicles to supervisors",
    ax_8: "Under your brand",
    ax_9: "Clip search and download",
