    ax_11: "Bulk driver upload",
    ax_12: "Clips by event with download from the dashboard",
    ax_13: "Create, assign and track work orders in the field with GPS: check-in with distance, time on site, live customer portal and price catalog.",
    ax_14: "Create action plans (NOT FIT)",
    ax_15: "Create and complete inspections",
    ax_16: "Create and manage records",
    ax_17: "Create and manage templates",
    ax_18: "Take care of your cargo's temperature,",
    ax_19: "Tell us your fleet size and what you need to improve. We'll prepare a personalized demo with no commitment.",
    ax_20: "From 10 to 50,000 vehicles. The platform grows with your business without migrations or changing providers.",
    ax_21: "Set minimum and maximum (°C) for each device; activate only the ones you want to monitor.",
    ax_22: "Personalized demo for your fleet",
    ax_23: "Real-time fleet dispatch and telemetry: operational control, trip assignment, overnight stay reporting and driver behavior alerts.",
    ax_24: "Automatically detects which vehicle each trailer is connected to, with a full history of hitches and unhitches.",
    ax_25: "Driver documents and licenses",
    ax_26: "With Notice, every alert your customers send lands on the right channel. No more missed calls, informal messages or alerts nobody sees.",
    ax_27: "Trailer ↔ vehicle hitch",
    ax_28: "Trailer ↔ vehicle hitch with history",
    ax_29: "Instant delivery to the driver's device",
