    ax_31: "Export to CSV, Excel and PDF for auditing and compliance.",
    ax_32: "Digital signature and photos in every inspection",
    ax_33: "GPS and drivers synced with every camera",
    ax_34: "Manage your fleet's preventive and corrective maintenance with detailed costs and automatic reminders based on mileage or engine hours read from the GPS.",
    ax_35: "Manage ratings and scoring",
    ax_36: "Manage company subaccounts",
    ax_37: "Public transit route management: GPS tracking of buses, schedule and interval control, geofences, routes and a real-time control center.",
