    ax_39: "TagRadar works with no GPS and no SIM. Turn it on in your customer's account and start billing them for asset tracking in days, not months.",
    ax_40: "Start and end of shift by scanning the assigned vehicle's QR code",
    ax_41: "Install CamFleet and give your customers visual evidence of everything that happens in every vehicle, around the clock, under your brand.",
    ax_42: "Inventory and status of each asset",
    ax_43: "Higher open rate than any other channel",
    ax_44: "Monitor your refrigerated units' temperature in real time, set the allowed range for each one, automatically detect excursions (when the temperature goes out of range) and keep the history for auditing and compliance.",
    ax_45: "Monitor your refrigerated cargo's temperature in real time: ranges per unit, excursion alerts and exportable history.",
    ax_46: "More than 200 vehicles",
    ax_47: "Our team supports you from the initial setup to full adoption by your team.",
