    ax_57: "Theft or unauthorized movement, prolonged inactivity, low battery and signal loss — each one notified in real time.",
    ax_58: "Routes, stops and students; live bus for parents; onboard app for driver and monitor; attendance with QR/RFID/geofence and reports.",
