    feat_title:'One platform.<br>Everything you need.',
    feat_desc:'From real-time tracking to advanced analytics — every tool designed to reduce costs and maximize operational control.',
    feat_1_title:'Real-time monitoring', feat_1_desc:'See the exact position of every unit, speed, engine status and route history from any device.',
    feat_2_title:'Smart geofences', feat_2_desc:'Define virtual zones on the map and receive automatic alerts when any unit enters or exits, in real time.',
    feat_3_title:'Reports & analytics', feat_3_desc:'Detailed reports on routes, times, stops, fuel and driver behavior. Export as PDF, Excel or CSV.',
    feat_4_title:'Automatic alerts', feat_4_desc:'Instant notifications for speeding, inactivity, restricted zone entries and critical fleet events.',
    feat_5_title:'Multi-user & roles', feat_5_desc:'Manage multiple companies, drivers, supervisors and operators with granular permissions per module and function.',
    feat_6_title:'Mobile access', feat_6_desc:'Native apps for iOS and Android. Drivers, supervisors and inspectors access from any mobile device.',
