    driveiq_feat_1:'Driving score per driver', driveiq_feat_2:'Events: speed, braking, acceleration', driveiq_feat_3:'Vehicle groups and analytics', driveiq_feat_4:'Up to 15% fuel reduction', driveiq_link:'Learn about DriveIQ',
