    how_desc:'No complex installations. No months of implementation. Your fleet, connected and monitored from day one.',
    step_1_title:'Connect your fleet', step_1_desc:'Install compatible GPS devices in your vehicles. We support over 900 models. Our team guides you every step of the way.',
    step_2_title:'Configure your ecosystem', step_2_desc:'Activate the apps you need, load your driver team, define zones and alerts. The platform adapts to your operation.',
    step_3_title:'Control and optimize', step_3_desc:'Monitor in real time, review reports, receive alerts and make decisions with real data. Your operation always in control.',
    ind_label:'Industries we serve', ind_title:'Solutions for every industry',
    ind_desc:'Appogio adapts to the specific needs of each sector with specialized configurations, modules and reports.',
    ind_1_title:'Logistics & transport', ind_1_desc:'Route control, delivery times, drivers and load efficiency in large-scale distribution operations.',
    ind_2_title:'Construction', ind_2_desc:'Tracking of heavy machinery, site assets and personnel. Control of operating hours and preventive maintenance.',
    ind_3_title:'Passenger transport', ind_3_desc:'Bus and taxi fleet management: routes, drivers, inspections and compliance with safety regulations.',
    ind_4_title:'Industry & manufacturing', ind_4_desc:'Internal fleet control, plant asset tracking and dispatch coordination in industrial environments.',
    ind_5_title:'Last mile', ind_5_desc:'Delivery route optimization, package traceability and delivery driver management in e-commerce operations.',
    ind_6_title:'Oil & Gas', ind_6_desc:'Vehicle monitoring in remote zones, fuel control and compliance with field safety protocols.',
    ind_7_title:'Emergency & health', ind_7_desc:'Real-time dispatch, ambulance traceability and medical inspections of emergency vehicles.',
    ind_8_title:'School transport', ind_8_desc:'Student routes, vehicle safety inspections and automatic notifications to parents and administrators.',
