    dq_badge:'Driving Analysis',
    dq_title:'Turn driving data into <span style="color:#F59E0B">preventive action</span>',
    dq_desc:'DriveIQ analyzes every driver\'s behavior in real time: speeding, harsh braking, aggressive acceleration and idle time. Scores, alerts and coaching to reduce accidents and fuel consumption.',
    dq_stat_1:'Fuel reduction',
    dq_stat_2:'Fewer road incidents',
    dq_stat_3:'Fleet coverage',
    dq_stat_4:'Continuous monitoring',
    dq_feat_title:'Everything you need to improve driving',
    dq_f1_title:'Driving score (0–100)',
    dq_f1_desc:'Real-time score per driver. Deducts points for speeding, harsh braking, aggressive acceleration, swerving, phone use, fatigue, seatbelt and idle time.',
    dq_f2_title:'8 types of events detected',
    dq_f2_desc:'Speeding, harsh braking, aggressive acceleration, sharp swerving, phone use while driving, driver fatigue, unfastened seatbelt and excessive idle time — each with severity and exact location.',
    dq_f3_title:'Automatic ranking and coaching',
    dq_f3_desc:'Comparative ranking across all company drivers. The system generates up to 3 personalized coaching tips based on each driver\'s most frequent events.',
    dq_f4_title:'Real-time vehicle panel',
    dq_f4_desc:'Exact position, current speed and online/offline status of each unit. Customizable vehicle types to adapt evaluation parameters to each category of your fleet.',
    dq_f5_title:'Vehicle groups',
    dq_f5_desc:'Organize your fleet into groups by zone, service type or shift. Filter events, scores and reports by group. Ideal for companies with multiple operations or branches.',
    dq_f6_title:'Native Appogio integration',
    dq_f6_desc:'Directly consumes data from your GPS platform. No additional configuration: vehicles, drivers and events already registered in Appogio appear automatically in DriveIQ.',
    dq_ss_title:'See DriveIQ in detail',
    dq_video_title:'DriveIQ in action',
    dq_cta_title:"Ready to sell your customers driver behaviour control?",
    dq_cta_desc:"Request a DriveIQ demo and offer your customers' fleets driver scoring, driving events and reports, under your brand.",
    dq_cta_btn:'Request DriveIQ Demo',
    ip_badge:'Digital Inspections',
    ip_title:'From paper to digital in <span style="color:#3B82F6">minutes. Frictionless.</span>',
    ip_desc:'InspectPro replaces physical forms with smart checklists, digital signature, geotagged photos and approval workflows. Everything is recorded, traceable and available as a PDF report instantly.',
    ip_stat_1:'Less time per inspection',
    ip_stat_2:'Record digitization',
    ip_stat_3:'Papers eliminated',
    ip_stat_4:'Customizable templates',
    ip_stat_4_val:'Unlimited',
    ip_feat_title:'Smart inspections from start to finish',
    ip_f1_title:'Unlimited customizable templates',
    ip_f1_desc:'Design, clone and edit checklists with text, photos, multiple choice, digital signature and rating. Each company configures its own forms to match its operation.',
    ip_f2_title:'Supervisor approval workflow',
    ip_f2_desc:'The supervisor approves ✅ or rejects ❌ with a reason. On rejection, the driver receives the inspection back with an orange notice and must correct it. Action plans are logged in the history.',
    ip_f3_title:'AI + license plate OCR',
    ip_f3_desc:'Parses physical forms from a photo using artificial intelligence. Automatic license plate OCR to register inspections without manually typing the plate number.',
    ip_f4_title:'Document expiry alerts',
    ip_f4_desc:'Monitors insurance, technical inspections, licenses and any vehicle document. Generates automatic alerts before expiry so the fleet always operates in compliance.',
    ip_f5_title:'PDF, CSV reports and dashboard',
    ip_f5_desc:'PDF reports with digital signature and geotagged photos. Export to CSV or ZIP. Compliance dashboard with expected vs completed inspections, trends and analytics.',
    ip_f6_title:'QR, push notifications and API',
    ip_f6_desc:'QR per vehicle or form. Push notifications to the driver when an inspection is rejected. API keys and webhooks for external system integration. Complete audit logs.',
    ip_roles_title:'Smart access for every role',
    ip_role1_badge:'Driver / User',
    ip_role1_title:'Field operations',
    ip_role2_badge:'Supervisor',
    ip_role2_title:'Quality control',
    ip_role3_badge:'Administrator / Manager',
    ip_role3_title:'Full operational control',
    ip_ss_title:'InspectPro in detail',
    ip_video_title:'See InspectPro in action',
    ip_cta_title:"Ready to sell digital inspections to your customers?",
    ip_cta_desc:"Take paper out of your customers' fleets: forms, signature, photos and a PDF of every inspection, under your brand.",
    ip_cta_btn:'Request InspectPro Demo',
    po_badge:'Driver Management',
    po_title:'Every driver, <span style="color:#DE6510">fully under control.</span>',
    po_desc:'PilotOS centralizes your driver team management: digital records, shift control, license and document expiry, performance rating and direct communication — all from an intuitive mobile app.',
    po_stat_1:'Road incident reduction',
    po_stat_2:'Digitized records',
    po_stat_3:'Expired documents without alert',
    po_stat_4:'Native Android & iOS app',
    po_feat_title:'The complete digital record for every driver',
    po_f1_title:'Driver management and bulk upload',
    po_f1_desc:'Create, edit and delete drivers. Upload up to 500 drivers at once via bulk import. Complete assignment history for each driver.',
    po_f2_title:'QR Check-in / Check-out',
    po_f2_desc:'The driver scans the vehicle QR to start and end their shift. The QR encodes the vehicle directly. The admin generates a unique QR per unit from the panel.',
    po_f3_title:'Integrated DriveIQ score',
    po_f3_desc:'Each driver sees their driving score (0–100) calculated in real time from DriveIQ: speed, braking, seatbelt, phone, fatigue and more. Automatic coaching based on their frequent events.',
    po_f4_title:'Pre-operational inspections',
    po_f4_desc:'The driver dashboard shows pending InspectPro inspections. When the inspection is completed, the status syncs automatically between both platforms.',
    po_f5_title:'Driver GPS tracking',
    po_f5_desc:'The driver reports their GPS position in real time during the active shift. The admin enables or disables tracking per driver. Management of tracking opt-out requests.',
    po_f6_title:'Real-time notifications',
    po_f6_desc:'The admin panel receives real-time SSE alerts every time a driver checks in or out. FCM push notifications to drivers when an inspection is rejected.',
    po_mobile_title:'In every driver\'s pocket',
    po_mobile_desc:'PilotOS works as a native app on Android and iOS. Drivers access their shifts, documents and messages without hassle. No paper, no unnecessary calls.',
    po_mobile_btn:'See Live Demo',
    po_roles_title:'The right access for every role',
    po_role1_badge:'Driver',
    po_role1_title:'Daily operations',
    po_role2_badge:'Fleet Supervisor',
    po_role2_title:'Operational control',
    po_role3_badge:'Administrator / HR',
    po_role3_title:'Complete staff management',
