    po_video_title:'See PilotOS in action',
    po_cta_title:"Ready to sell driver management to your customers?",
    po_cta_desc:"Offer them a digital file for every driver, with expiry dates tracked automatically and everything reachable from anywhere, under your brand.",
    po_cta_btn:'Request PilotOS Demo',
    cf_badge:'Vehicle Cameras',
    cf_title:'Your fleet, <span style="color:#7C3AED">seen in real time.</span>',
    cf_desc:'CamFleet integrates dashcam and cabin cameras with your GPS platform. Live streaming, continuous recording with cloud backup, automatic event detection (braking, collisions, drowsiness) and instant legal evidence for any incident.',
    cf_stat_1:'Continuous recording',
    cf_stat_2:'To access live recording',
    cf_stat_3:'Event detection accuracy',
    cf_stat_4:'Local + encrypted cloud backup',
    cf_feat_title:'More than a camera. A complete surveillance system.',
    cf_f1_title:'HLS / RTSP / WebRTC streaming',
    cf_f1_desc:'Watch all cameras live from the browser. The MediaMTX server retransmits the dashcam\'s JT1078 stream in HLS, RTSP and WebRTC with no plugins or apps required.',
    cf_f2_title:'Native JT808 / JT1078 protocol',
    cf_f2_desc:'Direct connection with Jimi and Concox dashcams (JC181, JC450, DC600) via JT808/JT1078 protocol. No external converters: the camera connects directly to the server.',
    cf_f3_title:'Event clips + download',
    cf_f3_desc:'Each event generates an associated video clip: event type, vehicle, date and time. Download any clip from the panel without accessing the physical device.',
    cf_f4_title:'WhatsApp alerts with evidence',
    cf_f4_desc:'Configure alert contacts per vehicle. When an event occurs, the system sends the notice via WhatsApp with the video clip attached as immediate evidence.',
    cf_f5_title:'GPS + synchronized drivers',
    cf_f5_desc:'Each camera has an associated vehicle and optionally a driver. The map shows real-time position and you can view the stream directly from the vehicle pin.',
    cf_f6_title:'Event dashboard by type and day',
    cf_f6_desc:'Executive summary with total cameras, active streams, events by type and daily trend. Identify vehicles with the most incidents at a glance.',
    cf_hw_title:'Works with the equipment you already have',
    cf_hw_desc:'CamFleet supports the leading vehicle camera manufacturers. If you already have hardware installed, it\'s probably compatible.',
    cf_hw4_title:'Another model?',
    cf_hw4_desc:'Check compatibility with your current hardware, no commitment',
    cf_ss_title:'CamFleet in detail',
    cf_cta_title:"Ready to sell your customers on-board video?",
    cf_cta_desc:"Request a CamFleet demo and offer your customers the onboard video that protects their operation, under your brand.",
    cf_cta_btn:'Request CamFleet Demo',
    tr_badge:'BLE Asset Tracking',
    tr_title:'Know where <span style="color:#10B981">every asset is, always.</span>',
    tr_desc:'TagRadar uses long-life BLE tags detected by fixed or mobile antennas. The map shows in real time the last antenna that detected each asset. No GPS, no SIM: works indoors, in yards and warehouses where GPS doesn\'t reach.',
    tr_stat_1:'Latest generation technology',
    tr_stat_2:'Map update frequency',
    tr_stat_3:'Tag battery life',
    tr_stat_4:'No connectivity cost',
    tr_feat_title:'From inventory chaos to total control',
    tr_f1_title:'Last position by antenna',
    tr_f1_desc:'Each BLE tag is captured by the nearest antenna. The map shows in real time the position of the antenna that last detected it, updated every 20 seconds.',
    tr_f2_title:'Geofences with entry/exit alerts',
    tr_f2_desc:'Define zones for each asset or group. Receive an immediate alert when equipment enters or leaves the assigned area. Configurable per zone and asset.',
    tr_f3_title:'24-hour route history',
    tr_f3_desc:'Query the complete detection history of any asset in the last 24 hours: the antenna that saw it, exact time and position. Total traceability.',
    tr_f4_title:'Real-time asset states',
    tr_f4_desc:'<strong>Live</strong> (detected &lt;5 min ago), <strong>Recent</strong> (&lt;2 h) or <strong>Inactive</strong> (&gt;2 h). At a glance you know which assets are being monitored and which haven\'t reported recently.',
    tr_f5_title:'Asset and antenna management',
    tr_f5_desc:'Register, edit and delete tags with name and description. Check which antennas are active, when they last reported and how many assets they\'ve detected.',
    tr_f6_title:'Android app + SSO with Appogio',
    tr_f6_desc:'Access from the native Android app with the same GPS Software credentials. Antennas report via BLE scanner APK without additional hardware.',
    tr_uc_title:'For any industry with assets to track',
    tr_ss_title:'TagRadar in detail',
    tr_video_title:'See TagRadar in action',
    tr_cta_title:"Ready to sell asset-level tracking to your customers?",
    tr_cta_desc:"TagRadar works with no GPS and no SIM. Turn it on in your customer's account and start billing asset tracking from day one.",
    tr_cta_btn:'Request TagRadar Demo',
    no_badge:'Communication & Alerts',
    no_title:'The right message, <span style="color:#06B6D4">to the right channel.</span>',
    no_desc:'Notice unifies your fleet\'s operational communication: automatic GPS alerts, messages to drivers via WhatsApp or push, expiry notifications and mass announcements. All from a single panel, with full history.',
    no_stat_1:'Integrated communication channels',
    no_stat_2:'Alert delivery time',
    no_stat_3:'Auditable message history',
    no_stat_4:'Alerts without manual intervention',
    no_feat_title:'Operational communication that really works',
    no_f1_title:'Integrated WhatsApp',
    no_f1_desc:'Send alerts, reports and messages directly to the driver\'s WhatsApp. No additional apps: the driver receives it on the phone they already use.',
    no_f2_title:'Push notifications',
    no_f2_desc:'Push notifications segmented by driver, vehicle, route or zone. With delivery receipt and read confirmation from the PilotOS app.',
    no_f3_title:'Automatic GPS alerts',
    no_f3_desc:'Triggers automatic messages for geofence events, speeding, unscheduled stops or off-route vehicles — no per-event configuration needed.',
    no_f4_title:'Email and SMS',
    no_f4_desc:'Backup channel for critical alerts. Configure escalation rules: if the driver doesn\'t respond in X minutes, escalate to the supervisor by email.',
    no_f5_title:'Message templates',
    no_f5_desc:'Create reusable templates with dynamic variables ({name}, {vehicle}, {speed}) to speed up sending recurring operational messages.',
    no_f6_title:'History and audit',
    no_f6_desc:'Complete record of all communications: who sent, to whom, when and whether it was delivered. Exportable for audits and compliance reports.',
    no_mc_title:'One message, all channels',
    no_mc_desc:'Define an alert rule once and Notice automatically decides the best channel based on event type, urgency and recipient preferences.',
    no_ss_title:'Notice in detail',
    no_video_title:'See Notice in action',
